import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    arr = data[1:]
    limit = max(arr)
    spf = list(range(limit + 1))
    for i in range(2, int(limit**0.5) + 1):
        if spf[i] == i:
            for j in range(i*i, limit+1, i):
                if spf[j] == j:
                    spf[j] = i
    nim = 0
    for x in arr:
        count = 0
        while x > 1:
            x //= spf[x]
            count += 1
        nim ^= count
    print('Anna' if nim else 'Bruno')

if __name__ == '__main__':
    main()

