from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        starts = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            starts[b].append((a, i))
        best1 = best2 = 0
        count1 = 0
        top_id = -1
        base = 0
        gains = [0] * len(conflictingPairs)
        for r in range(1, n + 1):
            for a, i in starts[r]:
                if a > best1:
                    best2 = best1
                    best1 = a
                    count1 = 1
                    top_id = i
                elif a == best1:
                    count1 += 1
                elif a > best2:
                    best2 = a
            base += r - best1
            if count1 == 1:
                gains[top_id] += best1 - best2
        return base + max(gains)

