import sys

def main():
    input = sys.stdin.buffer.readline
    N, M, Q = map(int, input().split())
    edges = [None] * M
    for i in range(M):
        a, b, c = map(int, input().split())
        edges[i] = (a-1, b-1, c)
    queries = []
    closed = [False] * M
    for _ in range(Q):
        p = list(map(int, input().split()))
        if p[0] == 1:
            i = p[1]-1
            closed[i] = True
            queries.append((1, i))
        else:
            queries.append((2, p[1]-1, p[2]-1))
    INF = 10**30
    d = [[INF] * N for _ in range(N)]
    for i in range(N):
        d[i][i] = 0
    for i, (a,b,c) in enumerate(edges):
        if not closed[i]:
            d[a][b] = d[b][a] = c
    for k in range(N):
        dk = d[k]
        for i in range(N):
            dik = d[i][k]
            if dik == INF:
                continue
            di = d[i]
            for j in range(N):
                v = dik + dk[j]
                if v < di[j]:
                    di[j] = v
    answers = []
    for q in reversed(queries):
        if q[0] == 2:
            x,y = q[1],q[2]
            v = d[x][y]
            answers.append(str(v if v < INF else -1))
        else:
            a,b,c = edges[q[1]]
            da = [d[i][a] for i in range(N)]
            db = [d[i][b] for i in range(N)]
            for i in range(N):
                di = d[i]
                via_a = da[i] + c
                via_b = db[i] + c
                for j in range(N):
                    v = via_a + db[j]
                    w = via_b + da[j]
                    if v < di[j]: di[j] = v
                    if w < di[j]: di[j] = w
    print('\n'.join(reversed(answers)))

if __name__ == '__main__': main()

