class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        dp = [0] * (min(n, x) + 1)
        dp[0] = 1
        for i in range(n):
            ndp = [0] * len(dp)
            for k, v in enumerate(dp):
                if not v:
                    continue
                ndp[k] = (ndp[k] + v * k) % mod
                if k + 1 < len(dp):
                    ndp[k + 1] = (ndp[k + 1] + v * (x-k) * y) % mod
            dp = ndp
        return sum(dp) % mod

