class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n=len(s)
        # steps until 1 for each possible popcount
        steps=[0]*(n+1)
        for x in range(2,n+1):
            steps[x]=1+steps[x.bit_count()]
        eligible=[j for j in range(1,n+1) if steps[j] <= k-1]
        C=[[0]*(n+1) for _ in range(n+1)]
        for a in range(n+1):
            C[a][0]=C[a][a]=1
            for b in range(1,a): C[a][b]=(C[a-1][b-1]+C[a-1][b])%MOD
        ans=0; ones=0
        for i,ch in enumerate(s):
            if ch=='1':
                rem=n-i-1
                for j in eligible:
                    need=j-ones
                    if 0<=need<=rem: ans=(ans+C[rem][need])%MOD
                ones+=1
        return ans

