import sys
from collections import deque

def feasible(items, left, right):
    # Equality constraints are added first.
    vertices = list(range(1, max(max(s, t) for s, t in items[left:right + 1]) + 1))
    parent = list(range(len(vertices) + 1))
    size = [1] * (len(vertices) + 1)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for i in range(left, right + 1):
        s, t = items[i]
        a, b = find(s), find(t)
        if a != b:
            if size[a] < size[b]:
                a, b = b, a
            parent[b] = a
            size[a] += size[b]

    edges = set()
    indegree = {}
    nodes = set()
    for i in range(left, right + 1):
        s, t = items[i]
        if s > t:
            s, t = t, s
        a = find(s)
        for v in range(s + 1, t):
            b = find(v)
            if a == b:
                return False
            edge = (a, b)
            if edge not in edges:
                edges.add(edge)
                nodes.add(a)
                nodes.add(b)
                indegree[b] = indegree.get(b, 0) + 1
                indegree.setdefault(a, 0)
    q = deque(v for v in nodes if indegree.get(v, 0) == 0)
    seen = 0
    adj = {}
    for a, b in edges:
        adj.setdefault(a, []).append(b)
    while q:
        a = q.popleft()
        seen += 1
        for b in adj.get(a, ()):
            indegree[b] -= 1
            if indegree[b] == 0:
                q.append(b)
    return seen == len(nodes)

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, q = data[:3]
    p = 3
    items = []
    for _ in range(m):
        items.append((data[p], data[p + 1]))
        p += 2
    ans = []
    for _ in range(q):
        l, r = data[p] - 1, data[p + 1] - 1
        p += 2
        ans.append('Yes' if feasible(items, l, r) else 'No')
    sys.stdout.write('\n'.join(ans))

if __name__ == '__main__':
    main()

