def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    it=iter(data)
    H=next(it); W=next(it); X=next(it)
    P=next(it)-1; Q=next(it)-1
    a=[[next(it) for _ in range(W)] for _ in range(H)]
    seen=[[False]*W for _ in range(H)]
    seen[P][Q]=True
    strength=a[P][Q]
    heap=[]
    def add(i,j):
        if 0<=i<H and 0<=j<W and not seen[i][j]:
            seen[i][j]=True
            heapq.heappush(heap,(a[i][j],i,j))
    for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
        add(P+di,Q+dj)
    while heap:
        s,i,j=heapq.heappop(heap)
        if s*X>=strength:
            break
        strength+=s
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            add(i+di,j+dj)
    print(strength)

if __name__=='__main__': main()

