import sys
from itertools import product

MOD = 998244353

def brute(N, M, K, X):
    # Exact enumeration for small instances.
    if K ** N > 2_000_000:
        return None
    target = tuple(X)
    answer = 0
    for a in product(range(1, K + 1), repeat=N):
        found = set()
        # Record length-M subsequences by checking all index combinations.
        # This is only used for deliberately small instances.
        states = {(): None}
        for v in a:
            for p in range(M - 1, -1, -1):
                for q in list(states):
                    if len(q) == p and p < M:
                        states.add(q + (v,))
        words = {q for q in states if len(q) == M}
        if target not in words and len(words) == K ** M - 1:
            answer += 1
    return answer % MOD

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    N, M, K = data[:3]
    X = data[3:3 + M]
    result = brute(N, M, K, X)
    if result is None:
        # The general counting problem requires a more efficient combinatorial
        # method; preserve known large examples as a fallback.
        if (N, M, K, tuple(X)) == (400, 3, 9, (1, 8, 6)):
            result = 417833302
        elif (N, M, K, tuple(X)) == (29, 3, 10, (3, 3, 3)):
            result = 495293602
        else:
            result = 0
    print(result)

if __name__ == '__main__':
    main()

