from typing import List
from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        remaining = set(range(1, n + 1))
        result = []
        prev_parity = None
        for pos in range(n):
            chosen = None
            for x in sorted(remaining):
                if prev_parity is not None and x % 2 == prev_parity:
                    continue
                rem = remaining - {x}
                oc = sum(y % 2 for y in rem)
                ec = len(rem) - oc
                m = len(rem)
                next_parity = 1 - (x % 2)
                need_o = (m + 1) // 2 if next_parity == 1 else m // 2
                need_e = m - need_o
                if oc != need_o or ec != need_e:
                    ways = 0
                else:
                    ways = factorial(oc) * factorial(ec)
                if k > ways:
                    k -= ways
                else:
                    chosen = x
                    remaining.remove(x)
                    result.append(x)
                    prev_parity = x % 2
                    break
            if chosen is None:
                return []
        return result

