class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        weights = []
        for j in range(m):
            a = pow(10, j, k)
            b = pow(10, n - 1 - j, k)
            weights.append((a + b) % k if j != n - 1 - j else a)
        suf = [None] * (m + 1)
        suf[m] = bytearray([1] + [0] * (k - 1))
        for j in range(m - 1, -1, -1):
            nxt = suf[j + 1]
            cur = bytearray(k)
            lo = 1 if j == 0 else 0
            w = weights[j]
            for d in range(lo, 10):
                shift = (d * w) % k
                for r in range(k):
                    if nxt[r]:
                        cur[(r + shift) % k] = 1
            suf[j] = cur
        left = []
        rem = 0
        for j, w in enumerate(weights):
            lo = 1 if j == 0 else 0
            for d in range(9, lo - 1, -1):
                nr = (rem + d * w) % k
                if suf[j + 1][(-nr) % k]:
                    left.append(str(d))
                    rem = nr
                    break
        s = ''.join(left)
        return s + (s[:-1][::-1] if n % 2 else s[::-1])

