from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        parent[0] = 0
        order = [0]
        for u in order:
            for v, w in graph[u]:
                if v != parent[u]:
                    parent[v] = u
                    order.append(v)

        free = [0] * n  # parent edge absent
        used = [0] * n  # parent edge present
        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += free[v]
                    gains.append(w + used[v] - free[v])
            gains.sort(reverse=True)
            positive = [g for g in gains if g > 0]
            free[u] = base + sum(positive[:k])
            used[u] = base + sum(positive[:max(0, k - 1)])
        return free[0]

