class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        a, rest = p.split('*', 1)
        b, c = rest.split('*', 1)

        def starts_of(t):
            if not t:
                return list(range(n + 1))
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        def next_table(t):
            occ = starts_of(t)
            nxt = [n + 1] * (n + 2)
            k = len(occ) - 1
            for i in range(n, -1, -1):
                while k >= 0 and occ[k] >= i:
                    k -= 1
                # Easier via descending pointer is awkward; use indexed occurrence scan below
            pos = n + 1
            for i in range(n, -1, -1):
                if i in occ:
                    pos = i
                nxt[i] = pos
            return nxt

        # Build occurrence indicator and suffix-next tables.
        def make_next(t):
            occ = starts_of(t)
            flags = bytearray(n + 1)
            for x in occ:
                flags[x] = 1
            nxt = [n + 1] * (n + 1)
            q = n + 1
            for i in range(n, -1, -1):
                if flags[i]: q = i
                nxt[i] = q
            return occ, nxt

        occ_a, _ = make_next(a)
        _, nb = make_next(b)
        _, nc = make_next(c)
        ans = n + 1
        for x in occ_a:
            y = nb[x + len(a)]
            if y <= n:
                z = nc[y + len(b)]
                if z <= n:
                    ans = min(ans, z + len(c) - x)
        return -1 if ans == n + 1 else ans

