import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    g = [[] for _ in range(n)]
    k = 2
    for _ in range(m):
        x, y, z = data[k]-1, data[k+1]-1, data[k+2]
        k += 3
        g[x].append((y, z))
        g[y].append((x, z))
    p = [None] * n
    ans = [0] * n
    for start in range(n):
        if p[start] is not None:
            continue
        p[start] = 0
        q = [start]
        comp = []
        for v in q:
            comp.append(v)
            for w, z in g[v]:
                val = p[v] ^ z
                if p[w] is None:
                    p[w] = val
                    q.append(w)
                elif p[w] != val:
                    print(-1)
                    return
        shift = 0
        for bit in range(31):
            ones = sum((p[v] >> bit) & 1 for v in comp)
            zeros = len(comp) - ones
            if zeros < ones:
                shift |= 1 << bit
        for v in comp:
            ans[v] = p[v] ^ shift
    print(*ans)

if __name__ == '__main__':
    main()

