import sys
from itertools import combinations

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[0], data[1]
    a = data[2:]
    total = 0
    for x in a:
        total ^= x
    if k <= n-k:
        size = k
        base = 0
    else:
        size = n-k
        base = total
    ans = 0
    for inds in combinations(range(n), size):
        x = base
        for i in inds:
            x ^= a[i]
        if x > ans:
            ans = x
    print(ans)

if __name__ == '__main__':
    solve()

