import random, subprocess

def fast(N,W,its):
 d=[-10**30]*(W+1);d[0]=0
 from collections import deque
 for w,v in its:
  nd=[-10**30]*(W+1)
  for r in range(min(w,W+1)):
   q=deque();t=0
   for i in range(r,W+1,w):
    if d[i]>-10**30:
     b=d[i]-t*t
     while len(q)>=2:
      m1,b1=q[-2];m2,b2=q[-1]
      if (b1-b2)*(t-m2)>=(b2-b)*(m2-m1):q.pop()
      else:break
     q.append((t,b))
    if q:
     x=2*t-v
     while len(q)>1 and q[1][0]*x+q[1][1]>=q[0][0]*x+q[0][1]:q.popleft()
     m,b=q[0];nd[i]=t*v-t*t+m*x+b
    t+=1
  d=nd
 return max(d)
def brute(W,its):
 d=[0]+[-10**30]*W
 for w,v in its:
  nd=[-10**30]*(W+1)
  for x in range(W+1):
   if d[x]>-10**30:
    for k in range((W-x)//w+1):nd[x+k*w]=max(nd[x+k*w],d[x]+k*v-k*k)
  d=nd
 return max(d)
for _ in range(1000):
 W=random.randint(1,25);N=random.randint(1,8);its=[(random.randint(1,W),random.randint(1,30)) for i in range(N)]
 a=fast(N,W,its);b=brute(W,its)
 if a!=b: print('bad',W,its,a,b);break
else:print('all good')

